import{_ as l,K as r,a,c as n,ac as t,b as s,q as i}from"./chunks/framework.BSuaGltH.js";const q=JSON.parse('{"title":"k8s组件","description":"k8s组件","frontmatter":{"title":"k8s组件","description":"k8s组件","sources":[{"repository":"jekyall_blog","file":"_posts/DevOps/云原生/kubernetes(k8s)old/other/k8s组件.md"}],"showdocs":{"topics":[{"id":"kubernetes","title":"Kubernetes","link":"/topics/kubernetes/"},{"id":"architecture","title":"架构风格与模块边界","link":"/topics/architecture/"}],"kind":"知识专题","scope":"historical","audience":"general","group":"容器与运维","summary":"k8s组件","status":"active","related":[{"title":"Kubernetes 架构与 API","link":"/systems/kubernetes/plus/subjects/02-architecture-and-api","kind":"知识专题","scope":"general","audience":"general"},{"title":"istio 1.7","link":"/systems/kubernetes/plus/subjects/istio-1.7","kind":"知识专题","scope":"historical","audience":"general"},{"title":"Kubernetes 操作与命令","link":"/systems/kubernetes/plus/ecosystem/kubernetes-general-general","kind":"命令","scope":"general","audience":"general"},{"title":"Kubernetes 排障：Pod、发布、网络与存储","link":"/systems/kubernetes/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Kubernetes 排障：Pod、发布、网络与存储 · 按 Pod、Service 与端点定位故障至Pod 运行但服务不可达的复盘","link":"/systems/kubernetes/troubleshooting-part-02","kind":"故障排查","scope":"general","audience":"general"}],"prev":false,"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":false},"headers":[],"relativePath":"systems/kubernetes/plus/subjects/k8s组件.md","filePath":"systems/kubernetes/plus/subjects/k8s组件.md"}'),u={name:"systems/kubernetes/plus/subjects/k8s组件.md"};function c(d,e,b,k,p,h){const o=r("ArticleImage");return a(),n("div",null,[e[0]||(e[0]=t('<h1 id="k8s组件" tabindex="-1">k8s组件 <a class="header-anchor" href="#k8s组件" aria-label="Permalink to &quot;k8s组件&quot;">​</a></h1><p>本文为旧组件笔记，保留原分类与历史名词，不作为当前版本运行时或令牌默认行为清单。当前架构见<a href="/systems/kubernetes/plus/subjects/02-architecture-and-api">控制面与API</a>。</p><h2 id="k8s介绍" tabindex="-1">k8s介绍 <a class="header-anchor" href="#k8s介绍" aria-label="Permalink to &quot;k8s介绍&quot;">​</a></h2><h3 id="容器优势" tabindex="-1">容器优势 <a class="header-anchor" href="#容器优势" aria-label="Permalink to &quot;容器优势&quot;">​</a></h3><blockquote><p>容器因具有许多优势而变得流行起来。下面列出了容器的一些好处：</p></blockquote><ul><li>敏捷应用程序的创建和部署：与使用 VM 镜像相比，提高了容器镜像创建的简便性和效率。</li><li>持续开发、集成和部署：通过快速简单的回滚(由于镜像不可变性)，提供可靠且频繁的容器镜像构建和部署。</li><li>关注开发与运维的分离：在构建/发布时而不是在部署时创建应用程序容器镜像，从而将应用程序与基础架构分离。</li><li>可观察性不仅可以显示操作系统级别的信息和指标，还可以显示应用程序的运行状况和其他指标信号。</li><li>跨开发、测试和生产的环境一致性：在便携式计算机上与在云中相同地运行。</li><li>云和操作系统分发的可移植性：可在 Ubuntu、RHEL、CoreOS、本地、Google Kubernetes Engine 和其他任何地方运行。</li><li>以应用程序为中心的管理：提高抽象级别，从在虚拟硬件上运行 OS 到使用逻辑资源在 OS 上运行应用程序。</li><li>松散耦合、分布式、弹性、解放的微服务：应用程序被分解成较小的独立部分，并且可以动态部署和管理 - 而不是在一台大型单机上整体运行。</li><li>资源隔离：可预测的应用程序性能。</li><li>资源利用：高效率和高密度。</li></ul><h3 id="为什么需要kubernets" tabindex="-1">为什么需要kubernets <a class="header-anchor" href="#为什么需要kubernets" aria-label="Permalink to &quot;为什么需要kubernets&quot;">​</a></h3><ul><li>知识点 <ul><li><a href="https://www.jdon.com/project/canary.html" target="_blank" rel="noopener noreferrer">https://www.jdon.com/project/canary.html</a></li></ul></li></ul><h4 id="kubernets" tabindex="-1">kubernets <a class="header-anchor" href="#kubernets" aria-label="Permalink to &quot;kubernets&quot;">​</a></h4><ul><li>服务发现和负载均衡</li></ul><blockquote><p>可以使用dns名称或者自己IP地址公开容器；如果流量很大，可以负载均衡并分配网络流量使部署稳定</p></blockquote><ul><li>储存编排</li></ul><blockquote><p>可以自动挂载选择储存系统（本地储存、公共云）</p></blockquote><ul><li>自动部署和回滚 <ul><li><a href="https://www.jianshu.com/p/7411d15215b5" target="_blank" rel="noopener noreferrer">参考文章</a></li><li><a href="https://kubernetes.io/zh/docs/tasks/manage-daemon/rollback-daemon-set/" target="_blank" rel="noopener noreferrer">官方文章</a></li></ul></li></ul><blockquote><p>自动化部署创建新容器，删除现有容器并将它们所有的资源用于新容器</p></blockquote><ul><li>自动二进制打包</li></ul><blockquote><p>可以指定容器所需CPU和内存(RAM);当指定资源请求时，k8s做出更好的决策来管理容器资源</p></blockquote><ul><li>自我修复</li></ul><blockquote><p>重启失败容器，替换容器、杀死不响应用户定义运行状况检查的容器，并且在准备好服务之前不会通知给客户端</p></blockquote><ul><li>密钥与配置管理</li></ul><blockquote><p>可以存储敏感信息（密码、OAuth、ssh密钥）；可以在不重建容器镜像情况下部署更新迷药和应用配置，无需在堆栈中暴露密钥</p></blockquote><h3 id="kubernets-组件" tabindex="-1">Kubernets 组件 <a class="header-anchor" href="#kubernets-组件" aria-label="Permalink to &quot;Kubernets 组件&quot;">​</a></h3>',22)),s("p",null,[i(o,{src:"/sources/remote/8a4176c05fb88e005f4c62e0.png",alt:"Kubernetes 集群"})]),e[1]||(e[1]=t('<h4 id="kubernetes-control-plane-控制平面组件" tabindex="-1">Kubernetes Control Plane（控制平面组件） <a class="header-anchor" href="#kubernetes-control-plane-控制平面组件" aria-label="Permalink to &quot;Kubernetes Control Plane（控制平面组件）&quot;">​</a></h4><blockquote><p>控制面负责全局决策（如调度）及控制循环。replicas 表示目标 Pod 副本数，不是节点数；控制器依据期望状态创建或替换 Pod。控制面部署位置与高可用由集群方案决定，不能从单机安装脚本推导生产拓扑。</p></blockquote><ul><li>kube-api-server</li></ul><blockquote><p>主节点上负责提供Kubernets Api 服务组件；是控制面的前端；可以水平扩缩、部署多个实例可以扩缩</p></blockquote><ul><li>etcd</li></ul><blockquote><p>是K/V存储数据库；可以作为所有集群数据后台数据（配置....）；<a href="https://etcd.io/docs" target="_blank" rel="noopener noreferrer">etcd 文档</a></p></blockquote><ul><li>kube-scheduler（调度程序）</li></ul><blockquote><p>主节点上的组件、监视新创建的为指定运行的Pod ，并选择节点让Pod在上面运行；调度决策考虑的因素包括单个Pod 和Pod集合的资源需求、硬件/软件/策略约束、亲和性和反亲和性规范、数据位置、工作负载间的干扰和最后时限</p></blockquote><ul><li>kube-controller-manager（控制器） <ul><li>节点控制（Node Controller）:负责在节点出现故障进行通知和响应</li><li>副本控制器（Replication Controller）:负责系统中每个副本控制器对象维护正确数量Pod（维护Pod副本）</li><li>端点控制器（Endpoints Controller）:填充端点（Endpoints【endpoint是k8s集群中的一个资源对象，存储在etcd中，用来记录一个service对应的所有pod的访问地址】<a href="https://www.cnblogs.com/pu20065226/p/10647775.html" target="_blank" rel="noopener noreferrer">参考文章</a>）对象（即加入Server 与 Pod）</li><li>服务账户和令牌控制器（Service Account &amp; Token Controllers）:维护默认 ServiceAccount 等对象；令牌的投射和自动创建行为须按版本核对，不把旧的长期令牌默认行为推广到当前集群</li></ul></li></ul><blockquote><p>在主节点上运行控制器(控制器通过 apiserver 监控集群的公共状态，并致力于将当前状态转变为期望的状态)的组件，内含多个逻辑控制器，常在同一管理器进程运行，不能同时称为各自独立进程</p></blockquote><ul><li>cloud-controller-manager <a href="https://kubernetes.io/zh/docs/concepts/overview/components/#%E4%BA%91%E6%8E%A7%E5%88%B6%E5%99%A8%E7%AE%A1%E7%90%86%E5%99%A8-cloud-controller-manager" target="_blank" rel="noopener noreferrer">官方文档</a><ul><li>节点控制器</li><li>路由控制器</li><li>服务控制器</li><li>数据卷控制器</li></ul></li></ul><h4 id="kubernets-nodes-doc" tabindex="-1">kubernets Nodes <a href="https://kubernetes.io/zh/docs/concepts/overview/components/#node-%E7%BB%84%E4%BB%B6" target="_blank" rel="noopener noreferrer">doc</a> <a class="header-anchor" href="#kubernets-nodes-doc" aria-label="Permalink to &quot;kubernets Nodes [doc](https://kubernetes.io/zh/docs/concepts/overview/components/#node-%E7%BB%84%E4%BB%B6)&quot;">​</a></h4><blockquote><p>node组件在每个node上运行，维护运行Pod并提供Kubernets运行环境</p></blockquote><ul><li>kubelet</li></ul><blockquote><p>在集群中每个节点上运行的<strong>代理</strong>，保证容器运行在Pod中；kubelet接收一组通过各类机制提供给他的PodSpecs，确保容器处于运行状态且健康、kubelet 不会管理不是由Kubernets 创建的容器</p></blockquote><ul><li>kube-proxy</li></ul><blockquote><p>kube-proxy 实现 Service 虚拟 IP 的部分数据转发规则，把流量导向后端 Pod；具体实现和是否采用替代数据面由平台决定。它不提供应用层就绪或授权保证。</p></blockquote><h3 id="container-runtime-容器允许环境-doc" tabindex="-1">Container Runtime （容器允许环境）<a href="https://kubernetes.io/zh/docs/concepts/overview/components/#%E5%AE%B9%E5%99%A8%E8%BF%90%E8%A1%8C%E7%8E%AF%E5%A2%83-container-runtime" target="_blank" rel="noopener noreferrer">doc</a> <a class="header-anchor" href="#container-runtime-容器允许环境-doc" aria-label="Permalink to &quot;Container Runtime （容器允许环境）[doc](https://kubernetes.io/zh/docs/concepts/overview/components/#%E5%AE%B9%E5%99%A8%E8%BF%90%E8%A1%8C%E7%8E%AF%E5%A2%83-container-runtime)&quot;">​</a></h3><blockquote><p>负责运行容器的软件 原记录的运行时列表（包含旧 Docker 集成与 rktlet 历史项，不是当前支持矩阵）：</p></blockquote><ul><li>Docker</li><li>containerd</li><li>cri-o</li><li>rktlet</li></ul><h3 id="addons-插件" tabindex="-1">Addons（插件） <a class="header-anchor" href="#addons-插件" aria-label="Permalink to &quot;Addons（插件）&quot;">​</a></h3><p>插件使用 Kubernetes 资源 (DaemonSet, Deployment等) 实现集群功能。这些组件常放在 kube-system，但也可使用产品专用命名空间，并非一律属于 kube-system。</p><p>所选的插件如下所述：有关可用插件的扩展列表，请参见插件 (Addons)</p><h3 id="dns" tabindex="-1">DNS <a class="header-anchor" href="#dns" aria-label="Permalink to &quot;DNS&quot;">​</a></h3><p>尽管并非严格要求其他附加组件，但所有示例都依赖集群 DNS，因此所有 Kubernetes 集群都应具有 DNS。</p><p>除了您环境中的其他 DNS 服务器之外，集群 DNS 还是一个 DNS 服务器，它为 Kubernetes 服务提供 DNS 记录。</p><p>Cluster DNS 是一个 DNS 服务器，和您部署环境中的其他 DNS 服务器一起工作，为 Kubernetes 服务提供DNS记录。</p><p>Kubernetes 启动的容器自动将 DNS 服务器包含在 DNS 搜索中</p><h3 id="dashboard-用户界面" tabindex="-1">Dashboard（用户界面） <a class="header-anchor" href="#dashboard-用户界面" aria-label="Permalink to &quot;Dashboard（用户界面）&quot;">​</a></h3><p>Dashboard 是 Kubernetes 集群的通用基于 Web 的 UI。它使用户可以管理集群中运行的应用程序以及集群本身并进行故障排除</p><h3 id="容器资源监控" tabindex="-1">容器资源监控 <a class="header-anchor" href="#容器资源监控" aria-label="Permalink to &quot;容器资源监控&quot;">​</a></h3><p>容器资源监控将关于容器的一些常见的时间序列度量值保存到一个集中的数据库中，并提供用于浏览这些数据的界面</p><h3 id="集群层面日志" tabindex="-1">集群层面日志 <a class="header-anchor" href="#集群层面日志" aria-label="Permalink to &quot;集群层面日志&quot;">​</a></h3><p>集群层面日志 机制负责将容器的日志数据保存到一个集中的日志存储中，该存储能够提供搜索和浏览接口</p>',34))])}const f=l(u,[["render",c]]);export{q as __pageData,f as default};
